    <style>
        :root { --pink:#e75480; --ink:#342b2e; --soft:#fff5f7; --line:#f0dce2; }
        * { box-sizing:border-box; font-family:Arial,sans-serif; } body { margin:0; color:var(--ink); background:#fffafa; }
        .layout { display:grid; grid-template-columns:240px 1fr; min-height:100vh; }.side { padding:32px 24px; background:#4b3038; color:#fff; }.brand { color:#fff; font-family:Georgia,serif; font-size:30px; text-decoration:none; }.brand span { color:#ff8cab; }.side p { margin:38px 0 12px; color:#efc9d3; font-size:11px; font-weight:700; letter-spacing:.13em; }.side a:not(.brand) { display:block; margin:5px 0; border-radius:8px; padding:11px 13px; color:#f8e9ed; font-size:14px; text-decoration:none; }.side a.active,.side a:hover { background:#704553; }.content { padding:38px; }.top { display:flex; align-items:center; justify-content:space-between; gap:20px; }.top h1 { margin:0; font-family:Georgia,serif; font-size:32px; }.top a { color:var(--pink); text-decoration:none; font-size:14px; }.intro { color:#806f74; }.stats { display:grid; grid-template-columns:repeat(4,1fr); gap:18px; margin:28px 0; }.card { border:1px solid var(--line); border-radius:14px; padding:20px; background:#fff; }.card p { margin:0; color:#806f74; font-size:13px; }.card strong { display:block; margin-top:8px; color:var(--pink); font-size:30px; }.section { display:grid; grid-template-columns:1.5fr 1fr; gap:22px; }.panel { overflow:hidden; border:1px solid var(--line); border-radius:14px; background:#fff; }.panel h2 { margin:0; padding:19px 20px; border-bottom:1px solid var(--line); font-size:17px; }.table { width:100%; border-collapse:collapse; }.table th,.table td { padding:14px 20px; border-bottom:1px solid #f8edf0; text-align:left; font-size:13px; }.table th { color:#806f74; font-weight:600; }.badge { display:inline-block; border-radius:99px; padding:5px 9px; background:#fff0d9; color:#9a6517; font-size:11px; }.features { display:grid; gap:10px; padding:18px; }.feature { display:block; border-radius:10px; padding:14px; background:var(--soft); color:var(--ink); text-decoration:none; }.feature b,.feature span { display:block; }.feature span { margin-top:3px; color:#806f74; font-size:12px; } @media(max-width:850px){.layout{grid-template-columns:1fr}.side{padding:20px}.side p{margin:18px 0 8px}.side a:not(.brand){display:inline-block}.content{padding:24px}.stats,.section{grid-template-columns:1fr 1fr}.section>.panel:first-child{grid-column:1/-1}} @media(max-width:550px){.stats,.section{grid-template-columns:1fr}.section>.panel:first-child{grid-column:auto}.content{padding:18px}.table th:nth-child(3),.table td:nth-child(3){display:none}}
    </style>
</head>
